    /**
     * Method to retrieve the Metric via MetricFetchOneSummary
     * @param 	summary MetricFetchOneSummary 
     * @return 	MetricFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public Metric getMetric( MetricFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "MetricFetchOneSummary arg cannot be null" );
    	
    	Metric entity = null;
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	validator.validate( summary );    
        	
        	// --------------------------------------
        	// use queryGateway to send request to Find a Metric
        	// --------------------------------------
        	CompletableFuture<Metric> futureEntity = queryGateway.query(new FindMetricQuery( new LoadMetricFilter( summary.getMetricId() ) ), ResponseTypes.instanceOf(Metric.class));
        	
        	entity = futureEntity.get();
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate Metric with id " + summary.getMetricId();
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


